// Helper functions as per guidelines
function decode(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

function encode(bytes: Uint8Array) {
  let binary = '';
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
}

async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

const VoiceConcierge: React.FC<VoiceConciergeProps> = ({ onClose }) => {
  const [sessionState, setSessionState] = useState<'idle' | 'connecting' | 'active' | 'error'>('idle');
  const [status, setStatus] = useState('Elena is resting...');
  const [isSpeaking, setIsSpeaking] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [currentVisual, setCurrentVisual] = useState<typeof RESORT_IMAGES['mount-amanzi'] | null>(null);
  const [transcriptionHistory, setTranscriptionHistory] = useState<{ role: 'user' | 'model', text: string }[]>([]);

  const audioContextRef = useRef<AudioContext | null>(null);
  const outputAudioContextRef = useRef<AudioContext | null>(null);
  const nextStartTimeRef = useRef(0);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const sessionRef = useRef<any>(null);
  const streamRef = useRef<MediaStream | null>(null);
  const chatEndRef = useRef<HTMLDivElement>(null);

  // Refs for accumulating transcriptions during a turn
  const currentInputTranscription = useRef('');
  const currentOutputTranscription = useRef('');

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [transcriptionHistory]);

  const cleanup = useCallback(() => {
    if (sessionRef.current) { sessionRef.current.close(); sessionRef.current = null; }
    if (audioContextRef.current) { audioContextRef.current.close(); audioContextRef.current = null; }
    if (outputAudioContextRef.current) { outputAudioContextRef.current.close(); outputAudioContextRef.current = null; }
    if (streamRef.current) { streamRef.current.getTracks().forEach(track => track.stop()); streamRef.current = null; }
    sourcesRef.current.forEach(s => { try { s.stop(); } catch(e) {} });
    sourcesRef.current.clear();
    setSessionState('idle');
    setIsSpeaking(false);
    nextStartTimeRef.current = 0;
  }, []);

  const createPcmBlob = (data: Float32Array) => {
    const l = data.length;
    const int16 = new Int16Array(l);
    for (let i = 0; i < l; i++) {
      int16[i] = data[i] * 32768;
    }
    return {
      data: encode(new Uint8Array(int16.buffer)),
      mimeType: 'audio/pcm;rate=16000',
    };
  };

  const startSession = async () => {
    cleanup();
    setError(null);
    setSessionState('connecting');
    setStatus('Elena is waking up...');

    try {
      const apiKey = process.env.API_KEY;
      if (!apiKey || apiKey === 'undefined') {
        throw new Error("API Key not found. Please ensure your key is active.");
      }

      const stream = await navigator.mediaDevices.getUserMedia({ audio: true }).catch(() => {
        throw new Error("Microphone access blocked. Please allow access to talk to Elena.");
      });
      streamRef.current = stream;

      const ai = new GoogleGenAI({ apiKey: apiKey });
      audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      outputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-09-2025',
        callbacks: {
          onopen: () => {
            setSessionState('active');
            setStatus('Elena is listening...');
            if (audioContextRef.current) {
              const source = audioContextRef.current.createMediaStreamSource(stream);
              const scriptProcessor = audioContextRef.current.createScriptProcessor(4096, 1, 1);
              scriptProcessor.onaudioprocess = (e) => {
                const inputData = e.inputBuffer.getChannelData(0);
                const pcmBlob = createPcmBlob(inputData);
                sessionPromise.then(s => s?.sendRealtimeInput({ media: pcmBlob }));
              };
              source.connect(scriptProcessor);
              scriptProcessor.connect(audioContextRef.current.destination);
            }
          },
          onmessage: async (message: LiveServerMessage) => {
            // Handle Transcriptions
            if (message.serverContent?.inputTranscription) {
              currentInputTranscription.current += message.serverContent.inputTranscription.text;
              setStatus('Elena is hearing you...');
            }
            if (message.serverContent?.outputTranscription) {
              currentOutputTranscription.current += message.serverContent.outputTranscription.text;
              setStatus('Elena is speaking...');
            }

            if (message.serverContent?.turnComplete) {
              const userText = currentInputTranscription.current;
              const modelText = currentOutputTranscription.current;
              if (userText || modelText) {
                setTranscriptionHistory(prev => [
                  ...prev,
                  ...(userText ? [{ role: 'user' as const, text: userText }] : []),
                  ...(modelText ? [{ role: 'model' as const, text: modelText }] : [])
                ]);
              }
              currentInputTranscription.current = '';
              currentOutputTranscription.current = '';
              setStatus('Elena is listening...');
            }

            // Handle Tool Calls
            if (message.toolCall && message.toolCall.functionCalls) {
              for (const fc of message.toolCall.functionCalls) {
                if (fc.name === 'display_resort_visuals') {
                  const id = (fc.args as any).destination_id;
                  if (RESORT_IMAGES[id]) setCurrentVisual(RESORT_IMAGES[id]);
                  sessionPromise.then(s => s?.sendToolResponse({
                    functionResponses: [{ id: fc.id, name: fc.name, response: { result: "Image displayed successfully" } }]
                  }));
                }
              }
            }

            // Handle Audio Output
            const base64Audio = message.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;
            if (base64Audio && outputAudioContextRef.current) {
              setIsSpeaking(true);
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, outputAudioContextRef.current.currentTime);
              const buffer = await decodeAudioData(decode(base64Audio), outputAudioContextRef.current, 24000, 1);
              const source = outputAudioContextRef.current.createBufferSource();
              source.buffer = buffer;
              source.connect(outputAudioContextRef.current.destination);
              source.onended = () => {
                sourcesRef.current.delete(source);
                if (sourcesRef.current.size === 0) setIsSpeaking(false);
              };
              source.start(nextStartTimeRef.current);
              nextStartTimeRef.current += buffer.duration;
              sourcesRef.current.add(source);
            }

            if (message.serverContent?.interrupted) {
              sourcesRef.current.forEach(s => { try { s.stop(); } catch(e) {} });
              sourcesRef.current.clear();
              nextStartTimeRef.current = 0;
              setIsSpeaking(false);
              currentOutputTranscription.current = '';
              setStatus('Interrupted. Elena is listening...');
            }
          },
          onerror: (e: any) => { 
            console.error(e);
            setError("The concierge encountered a connection drift. Please wake her up again."); 
            setSessionState('error');
          },
          onclose: () => { setSessionState('idle'); }
        },
        config: {
          responseModalities: [Modality.AUDIO],
          tools: [{ functionDeclarations: [displayVisualsFn] }],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Zephyr' } } },
          inputAudioTranscription: {},
          outputAudioTranscription: {},
          systemInstruction: 'You are Elena, the elite Dream Vacation Club concierge. You are sophisticated, warm, and helpful. You help users plan luxury escapes across our portfolio. If a user asks to see a specific resort or category (Sun, Safari, Sea, Mountain, etc.), call display_resort_visuals. Always focus on the "luxury of time".',
        },
      });

      sessionRef.current = await sessionPromise;
    } catch (err: any) {
      setError(err.message || "Elena is currently unavailable.");
      setSessionState('error');
    }
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-slate-950/98 backdrop-blur-3xl" onClick={onClose}></div>

      <div className="relative w-full max-w-6xl flex flex-col items-center">
        <button onClick={onClose} className="absolute -top-16 right-0 w-12 h-12 bg-white/10 hover:bg-white/20 rounded-full flex items-center justify-center text-white transition-all z-50">
          <i className="fas fa-times"></i>
        </button>

        <div className="w-full grid lg:grid-cols-2 gap-8 items-stretch">

          {/* Visual & Status Section */}
          <div className="flex flex-col gap-6">
            <div className="relative aspect-video lg:aspect-square rounded-[2rem] overflow-hidden shadow-2xl bg-slate-900 border border-white/10 flex items-center justify-center group">
              {currentVisual ? (
                <div className="absolute inset-0 animate-[fadeIn_0.8s_ease-out]">
                  <img src={currentVisual.url} alt={currentVisual.name} className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-1000" />
                  <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-transparent to-transparent"></div>
                  <div className="absolute bottom-8 left-8 right-8 p-6 bg-white/5 backdrop-blur-2xl border border-white/10 rounded-2xl">
                    <h3 className="text-white text-xl font-bold serif">{currentVisual.name}</h3>
                    <p className="text-blue-300 text-[10px] font-bold uppercase tracking-widest">{currentVisual.location}</p>
                  </div>
                </div>
              ) : (
                <div className="text-center space-y-6 opacity-20">
                  <div className="relative">
                    <i className="fas fa-microphone-alt text-7xl text-white"></i>
                    {sessionState === 'active' && <div className="absolute inset-0 border-2 border-white rounded-full animate-ping"></div>}
                  </div>
                  <p className="text-white text-[10px] uppercase tracking-[0.4em] font-black">Elena Concierge System</p>
                </div>
              )}

              {isSpeaking && (
                <div className="absolute top-8 right-8 flex items-center gap-1.5 bg-black/40 backdrop-blur-md px-4 py-2 rounded-full border border-white/10">
                  <span className="text-[8px] font-bold uppercase text-blue-400 mr-2">Speaking</span>
                  {[...Array(4)].map((_, i) => (
                    <div key={i} className="w-1 h-3 bg-blue-400 rounded-full animate-bounce" style={{ animationDelay: `${i * 0.1}s` }}></div>
                  ))}
                </div>
              )}
            </div>

            <div className="bg-white/5 border border-white/10 rounded-2xl p-6 flex items-center justify-between">
              <div className="flex items-center gap-4">
                <div className={`w-3 h-3 rounded-full ${sessionState === 'active' ? 'bg-green-500 shadow-[0_0_15px_rgba(34,197,94,0.6)] animate-pulse' : sessionState === 'connecting' ? 'bg-amber-500 animate-spin' : 'bg-red-500'}`}></div>
                <span className="text-white font-medium text-sm tracking-wide">{status}</span>
              </div>

              {sessionState !== 'active' && (
                <button 
                  onClick={startSession} 
                  className="px-6 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-full text-[10px] font-black uppercase tracking-widest transition-all shadow-xl active:scale-95"
                >
                  Wake Elena
                </button>
              )}
            </div>
          </div>

          {/* Conversation History Section */}
          <div className="flex flex-col bg-slate-900/50 rounded-[2rem] border border-white/5 overflow-hidden h-[500px] lg:h-auto">
            <div className="p-6 border-b border-white/5 flex justify-between items-center bg-white/5">
              <h4 className="text-white text-xs font-bold uppercase tracking-[0.3em]">Live Interaction</h4>
              <i className="fas fa-comment-alt text-blue-500/50 text-sm"></i>
            </div>

            <div className="flex-grow overflow-y-auto p-8 space-y-6 scrollbar-hide">
              {transcriptionHistory.length === 0 && (
                <div className="h-full flex flex-col items-center justify-center text-center opacity-30 space-y-4">
                  <i className="fas fa-ghost text-4xl"></i>
                  <p className="text-xs uppercase tracking-widest font-bold">No conversation yet</p>
                </div>
              )}
              {transcriptionHistory.map((item, idx) => (
                <div key={idx} className={`flex ${item.role === 'user' ? 'justify-end' : 'justify-start'} animate-[fadeIn_0.5s_ease-out]`}>
                  <div className={`max-w-[80%] p-4 rounded-2xl text-sm leading-relaxed ${item.role === 'user' ? 'bg-blue-600/20 text-blue-100 border border-blue-600/30' : 'bg-white/5 text-slate-300 border border-white/10'}`}>
                    <p className="text-[10px] font-bold uppercase tracking-widest opacity-40 mb-1">{item.role === 'user' ? 'You' : 'Elena'}</p>
                    {item.text}
                  </div>
                </div>
              ))}
              <div ref={chatEndRef} />
            </div>

            <div className="p-6 bg-white/5 border-t border-white/5">
              <p className="text-[10px] text-white/30 italic text-center">
                Elena responds to your voice in real-time. Just start speaking.
              </p>
            </div>
          </div>
        </div>

        {error && (
          <div className="mt-8 p-4 bg-red-500/10 border border-red-500/20 rounded-xl max-w-lg w-full flex items-center gap-4">
            <i className="fas fa-exclamation-triangle text-red-500"></i>
            <p className="text-red-200 text-xs font-medium">{error}</p>
            <button onClick={startSession} className="ml-auto text-red-400 font-bold text-[10px] uppercase hover:text-white">Retry</button>
          </div>
        )}
      </div>
      <style dangerouslySetInnerHTML={{ __html: `
        @keyframes fadeIn { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }
        .scrollbar-hide::-webkit-scrollbar { display: none; }
        .scrollbar-hide { -ms-overflow-style: none; scrollbar-width: none; }
      `}} />
    </div>
  );
};

