           <p className="text-[8px] font-bold uppercase tracking-[0.3em] text-blue-400 mt-1">Concierge Elite</p>
        </div>

        {/* Current Visual (If any) */}
        <div className={`transition-all duration-1000 transform ${currentVisual ? 'scale-100 opacity-100 mb-12' : 'scale-90 opacity-0 h-0 overflow-hidden'}`}>
           <div className="relative inline-block group">
              <div className="absolute -inset-1 bg-gradient-to-r from-blue-600 to-indigo-600 rounded-2xl blur opacity-25 group-hover:opacity-50 transition duration-1000"></div>
              <div className="relative bg-slate-900 rounded-2xl overflow-hidden border border-white/10 shadow-2xl aspect-video w-[400px]">
                <img src={currentVisual?.url} className="w-full h-full object-cover" alt="" />
                <div className="absolute bottom-0 left-0 right-0 p-6 bg-gradient-to-t from-black/80 to-transparent">
                  <h3 className="text-white text-lg font-bold serif">{currentVisual?.name}</h3>
                  <p className="text-blue-300 text-[10px] font-bold uppercase tracking-widest">{currentVisual?.location}</p>
                </div>
              </div>
           </div>
        </div>

        {/* The Central Pulse Area */}
        <div className="relative mb-16">
          {/* Outer Ring */}
          <div className={`absolute -inset-8 rounded-full border border-white/5 transition-all duration-1000 ${sessionState === 'active' ? 'scale-100 opacity-100' : 'scale-75 opacity-0'}`}></div>

          {/* Main Pulse Ball */}
          <button 
            onClick={sessionState === 'active' ? undefined : startSession}
            className={`relative w-32 h-32 rounded-full flex items-center justify-center transition-all duration-700 shadow-2xl group ${
              sessionState === 'active' 
                ? isSpeaking ? 'bg-blue-600 shadow-blue-500/40' : 'bg-slate-800 border border-white/10' 
                : 'bg-white text-slate-900 scale-100 hover:scale-110 active:scale-95'
            }`}
          >
            {sessionState === 'active' ? (
               <div className="flex gap-1 items-center">
                 {[...Array(3)].map((_, i) => (
                   <div 
                     key={i} 
                     className={`w-1.5 h-6 rounded-full ${isSpeaking ? 'bg-white' : 'bg-blue-500/50'} ${isSpeaking ? 'animate-bounce' : 'animate-pulse'}`} 
                     style={{ animationDelay: `${i * 0.15}s` }}
                   />
                 ))}
               </div>
            ) : (
               <i className="fas fa-microphone text-2xl"></i>
            )}

            {/* Pulsing Aura */}
            {sessionState === 'active' && (
              <div className={`absolute inset-0 rounded-full animate-ping opacity-10 ${isSpeaking ? 'bg-blue-500' : 'bg-white'}`}></div>
            )}
          </button>
        </div>

        {/* Status & Ephemeral Transcription */}
        <div className="h-24 flex flex-col items-center justify-center gap-4">
           <span className="text-[10px] font-bold uppercase tracking-[0.3em] text-white/40">{status}</span>

           <div className={`transition-all duration-500 max-w-2xl ${currentText ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-4'}`}>
              <p className={`text-xl md:text-2xl serif leading-relaxed transition-colors duration-500 ${textRole === 'user' ? 'text-blue-300' : 'text-white'}`}>
                {currentText || "Speak your dream into reality..."}
              </p>
           </div>
        </div>

        {/* Controls */}
        <div className="mt-16 flex items-center gap-8">
           <button 
             onClick={onClose}
             className="text-[10px] font-bold uppercase tracking-widest text-white/30 hover:text-white transition-colors py-2 px-4 border border-white/10 rounded-full hover:bg-white/5"
           >
             {sessionState === 'active' ? 'Sleep' : 'Close'}
           </button>

           {sessionState === 'error' && (
              <button onClick={startSession} className="text-[10px] font-bold uppercase tracking-widest text-red-400 hover:text-red-300">
                Retry Connection
              </button>
           )}
        </div>

      </div>

      <style dangerouslySetInnerHTML={{ __html: `
        @keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }
        @keyframes pulseScale { 0%, 100% { transform: scale(1); } 50% { transform: scale(1.05); } }
      `}} />
    </div>
  );
};

