              {sessionState === 'active' ? (
                <div className="flex gap-1.5 h-8 items-end">
                  {[...Array(4)].map((_, i) => (
                    <div key={i} className={`w-1 bg-blue-400 rounded-full ${isSpeaking ? 'animate-[wave_1s_ease-in-out_infinite]' : 'h-2'}`} style={{ animationDelay: `${i * 0.15}s`, height: isSpeaking ? '100%' : '8px' }} />
