      <style dangerouslySetInnerHTML={{ __html: `
        @keyframes cardSlide { from { opacity: 0; transform: translateY(30px) scale(0.98); } to { opacity: 1; transform: translateY(0) scale(1); } }
        @keyframes wave { 0%, 100% { height: 20%; } 50% { height: 100%; } }
